import { test, expect } from '@playwright/test';

// Recording findings (from the session data — surfaced, never assertions):
//   - Session capture masks and drops sensitive fields (e.g. card numbers, passwords), so the recording may not carry every value this submit needs — if the replayed submit does not reach the expected page, a masked field the recording never captured needs its value added above it.
//   - This flow performs writes (form submissions). Run generated tests against a safe environment — point TARGET_APP_URL at staging/seeded data, never production.
//   - The asserted page text comes from one session — verify it is not user-specific before relying on it.

test.use({ viewport: { width: 1280, height: 720 } });

test('2', async ({ page, baseURL }) => {
  const consoleErrors: string[] = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });

  await page.goto('/flows/promo-3');
  // recorded action 1: fill "Your name"
  await page.getByTestId('promo-3-s1-field-0').fill('example'); // replaytest-marker: placeholder-value — placeholder value
  // recorded action 2: fill "Promo code"
  await page.getByTestId('promo-3-s1-field-1').fill('example'); // replaytest-marker: placeholder-value — placeholder value
  // recorded action 3: fill "Phone number 4"
  await page.getByTestId('promo-3-s1-field-3').fill('5555550100'); // replaytest-marker: placeholder-value — placeholder value
  // recorded action 4: click "Input"
  await page.getByTestId('promo-3-s1-field-2').click();
  // The recording witnessed a checkbox/radio interaction but not its resulting state
  // (masking/no captured value at the seam) — .check() assumes the common case;
  // use .uncheck() if this control should end up unchecked.
  // recorded action 5: fill "Enable option 3"
  await page.getByTestId('promo-3-s1-field-2').check();
  // recorded action 6: fill "Promo code"
  await page.getByTestId('promo-3-s1-field-1').fill('example'); // replaytest-marker: placeholder-value — placeholder value
  // If submit is blocked by a required field the recording didn't capture (e.g. a masked input), add its synthetic fill above.
  // recorded action 7: click "Apply code"
  await page.getByTestId('promo-3-s1-submit').click();

  await expect(page).toHaveURL(baseURL === undefined ? /^(?:[^/]+:\/\/[^/]+)?\/flows\/promo-3\/step\/[^\/]+$/ : new RegExp('^' + new URL(baseURL).origin.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\/flows\\/promo-3\\/step\\/[^\\/]+$')); // baseURL undefined: retain the sidecar's stored pattern unchanged.
  await expect(page).toHaveTitle('Acme Ops Console');
  expect(consoleErrors).toEqual([]); // replaytest-marker: console-clean — witnessed-clean: the session recording confirms 0 console errors
});
